-- ============================================================
-- Comprehensive metric_dictionary: blood (CBC with differential and
-- absolute counts, coagulation), liver, kidney, electrolytes, lipids,
-- cardiac and inflammatory markers, diabetes, thyroid, hormones,
-- vitamins / iron studies / trace elements, urine (routine,
-- microscopy and chemistry) and vitals.
--
-- Self-contained on purpose: it restates every entry from
-- 20260923000000_expand_metric_dictionary.sql, so a database that never
-- received that file ends up complete too. Safe to re-run.
--
-- Matching rules (standardizeLabReport.service.js): names are compared
-- lowercased with punctuation stripped, then word-order-insensitively,
-- then by a bracketed abbreviation ("Hematocrit (HCT)" -> HCT), then
-- without a method-only bracket ("CRP (Quantitative)" -> CRP). Qualifier
-- words ("Direct", "Free", "Absolute") are never dropped, so every
-- qualified spelling a lab prints is listed here. No spelling may belong
-- to two metrics; the generator that wrote this file checks that.
--
-- unit_standard is the unit trend charts use. unitConversion.service.js
-- understands lab spellings of it ("lakh/cu.mm", "mill/cumm", "thou/mm3",
-- "mcg/dL") and converts mass <-> molar per analyte, so a lab printing
-- mmol/L is converted rather than flagged. Qualitative results
-- ("Negative", "Trace", "Pale yellow") keep unit_standard null.
-- The micro sign is U+00B5, which is what Indian lab PDFs emit.
-- ============================================================


on conflict (standard_key) do update set
  display_name  = excluded.display_name,
  category      = excluded.category,
  unit_standard = excluded.unit_standard,
  -- Merge, never replace: keeps any spelling added by hand in the meantime.
  aliases       = array(select distinct unnest(metric_dictionary.aliases || excluded.aliases)),
  is_active     = true;
